  "implementation": "def solve(case):
    if 'threshold' not in case or 'calls' not in case:
        raise ValueError("Missing required fields 'threshold' or 'calls'")
    threshold = case['threshold']
    calls = case['calls']
    if not isinstance(threshold, (int, float)):
        raise ValueError("Threshold must be numeric")
    if not isinstance(calls, list):
        raise ValueError("Calls must be a list")
    accepted_ids = []
    diagnostics = []
    for call in calls:
        required = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
        for key in required:
            if key not in call:
                raise ValueError(f"Call missing required key: {key}")
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        tokens = call['prediction_tokens']
        parseable = call['parseable']
        if not isinstance(loss_without, (int, float)) or not isinstance(loss_with, (int, float)):
            raise ValueError("Loss values must be numeric")
        if not isinstance(tokens, int) or tokens <= 0:
            raise ValueError("prediction_tokens must be a positive integer")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")
        gain = loss_without - loss_with
        normalized_gain = gain / tokens
        accepted = parseable and (normalized_gain >= threshold)
        if accepted:
            accepted_ids.append(call_id)
        diagnostics.append({
            'call_id': call_id,
            'gain': round(gain, 8),
            'normalized_gain': round(normalized_gain, 8),
            'accepted': accepted
        })
    return {'accepted_call_ids': accepted_ids, 'diagnostics': diagnostics}"
}
